/**
 * @module modules/olMap/handler/routing/routingErrors
 */
import { RoutingErrorCodes, getRoutingErrorCodeFromError } from '../../../../domain/routing';
import { LevelTypes } from '../../../../store/notifications/notifications.action';

/**
 * Maps a {@link RoutingErrorCodes} to the user feedback which should be presented to the user.
 * @typedef {Object} RoutingErrorFeedback
 * @property {String} messageKey the i18n key of the user-friendly message
 * @property {module:store/notifications/notifications_action~LevelTypes} level the severity level of the feedback
 */

/**
 * Catalog object for the routing error feedback, keyed by {@link RoutingErrorCodes}.
 * @type {Object<RoutingErrorCodes, RoutingErrorFeedback>}
 */
export const RoutingError = Object.freeze({
	[RoutingErrorCodes.Http_Backend_400]: {
		messageKey: 'olMap_handler_routing_routingService_exception_bad_waypoints',
		level: LevelTypes.WARN
	},
	[RoutingErrorCodes.Http_Backend_500]: {
		messageKey: 'olMap_handler_routing_routingService_exception_technical',
		level: LevelTypes.ERROR
	}
});

/**
 * Returns the categorized routing error feedback for the given error.
 * @param {Error} error the error to categorize
 * @returns {RoutingErrorFeedback} the corresponding user feedback
 */
export const getRoutingError = (error) => RoutingError[getRoutingErrorCodeFromError(error)];

