import { CoordinateProposalType, RouteWarningCriticality, RoutingErrorCodes, RoutingStatusCodes, getRoutingErrorCodeFromError } from '../../src/domain/routing';

describe('RoutingStatusCodes', () => {
	it('provides an enum of all valid status codes', () => {
		expect(Object.keys(RoutingStatusCodes).length).toBe(6);

		expect(RoutingStatusCodes.Ok).toBe(200);
		expect(RoutingStatusCodes.Http_Backend_400).toBe(400);
		expect(RoutingStatusCodes.Http_Backend_500).toBe(500);
		expect(RoutingStatusCodes.Start_Destination_Missing).toBe(900);
		expect(RoutingStatusCodes.Destination_Missing).toBe(901);
		expect(RoutingStatusCodes.Start_Missing).toBe(902);
	});
});

describe('RoutingErrorCodes', () => {
	it('provides an enum of all valid error codes', () => {
		expect(Object.keys(RoutingErrorCodes).length).toBe(2);
		expect(Object.isFrozen(RoutingErrorCodes)).toBeTrue();

		expect(RoutingErrorCodes.Http_Backend_400).toBe(400);
		expect(RoutingErrorCodes.Http_Backend_500).toBe(500);
	});
});

describe('getRoutingErrorCodeFromError', () => {
	it('determines the error code of a backend 400 error', () => {
		const error = new Error('A route could not be retrieved: Http-Status 400');
		error.statusCode = 400;

		expect(getRoutingErrorCodeFromError(error)).toBe(RoutingErrorCodes.Http_Backend_400);
	});

	it('determines the error code of a backend 500 error', () => {
		const error = new Error('A route could not be retrieved: Http-Status 500');
		error.statusCode = 500;

		expect(getRoutingErrorCodeFromError(error)).toBe(RoutingErrorCodes.Http_Backend_500);
	});

	it('detects the error code within a nested cause chain', () => {
		const cause = new Error('A route could not be retrieved: Http-Status 400');
		cause.statusCode = 400;
		const error = new Error('Could not retrieve a routing result from the provider', { cause });

		expect(getRoutingErrorCodeFromError(error)).toBe(RoutingErrorCodes.Http_Backend_400);
	});

	it('treats errors without a status code as a technical error', () => {
		const networkError = new TypeError('Failed to fetch');
		const timeoutError = new Error('aborted');
		timeoutError.name = 'AbortError';

		expect(getRoutingErrorCodeFromError(networkError)).toBe(RoutingErrorCodes.Http_Backend_500);
		expect(getRoutingErrorCodeFromError(timeoutError)).toBe(RoutingErrorCodes.Http_Backend_500);
		expect(getRoutingErrorCodeFromError('just a message')).toBe(RoutingErrorCodes.Http_Backend_500);
	});
});

