+/**
+ * Distinguishes the cause of a routing failure.
+ * @readonly
+ * @enum {number}
+ */
+export const RoutingErrorCodes = Object.freeze({
+	Http_Backend_400: 400,
+	Http_Backend_500: 500
+});
+
+/**
+ * Determines the {@link RoutingErrorCodes} for a given error.
+ * Errors thrown by the routing backend are expected to carry the received HTTP status code
+ * in a `statusCode` property (potentially nested within the `cause` chain).
+ * All other failures (e.g. network or timeout errors) are treated as a technical backend issue.
+ * @param {Error} error the error to categorize
+ * @returns {RoutingErrorCodes} the corresponding error code
+ */
+export const getRoutingErrorCodeFromError = (error) => {
+	let currentError = error;
+	while (currentError) {
+		if (currentError.statusCode === RoutingErrorCodes.Http_Backend_400) {
+			return RoutingErrorCodes.Http_Backend_400;
+		}
+		if (currentError.statusCode === RoutingErrorCodes.Http_Backend_500) {
+			return RoutingErrorCodes.Http_Backend_500;
+		}
+		currentError = currentError.cause;
+	}
+	return RoutingErrorCodes.Http_Backend_500;
+};
